-- CCP 2 vacuum sealing: the monitoring is stated as it is performed, and FRM-606 is reshaped for it.
--
-- Owner and the SQF Practitioner's substitute, 2026-10-07:
--   * A pull test straight after sealing is not prudent: the film is still warm and a good seal can be
--     pulled open. The pull test moves to BOXING, on one cooled pouch per lot.
--   * At sealing every pouch is looked at as it comes off the sealer: seal sound, no air in the pouch.
--   * At boxing every pouch is looked at again; a pouch that has lost its vacuum is rejected.
--   * The gauge is read at set-up, not on every cycle. No hourly row: nobody can stop to write one.
-- Sealing stays CCP 2.
--
--   FRM-606  v2, GJM, effective 2026-10-07 (issued form, 0 entries, guarded):
--            - lot code entered ONCE at the top (new field lot_code); the lot_code column is removed
--              from both grids;
--            - check types: Set-up, In process, After a change or adjustment, End of run, At boxing
--              ("Hourly" is replaced by "In process");
--            - gauge reading, visual and pull test are optional per row (each belongs to some rows
--              only); new optional column "Pouches rejected since the last row";
--            - instructions, limits table, deviation steps and the operator's statement reworded.
--   FSQM-017 v14, GJM, effective 2026-10-07: the CCP 2 line and a revision note.
--   FSQM-016 draft: three lines reworded, one line added at boxing (146 -> 147), a revision note.
-- One UPDATE per document. The app release that reads the new shape is in the same pull request.

begin;

do $guard$
declare d record;
begin
  select status, revision, md5(content::text) as cmd5 into d from public.sop_documents where sop_number = 'FRM-606';
  if d.status is distinct from 'active' or d.revision is distinct from 'New' or d.cmd5 <> '9721eda5af1e2016dce434c74e931a8d' then
    raise exception 'FRM-606 is not as this migration expects (%).', d.cmd5;
  end if;
  if exists (select 1 from public.sop_document_responses r join public.sop_documents x on x.id = r.document_id where x.sop_number = 'FRM-606') then
    raise exception 'FRM-606 has entries; its lot code column cannot be moved without carrying their answers.';
  end if;
  select status, revision, md5(content::text) as cmd5, content->'procedure' as p into d from public.sop_documents where sop_number = 'FSQM-017';
  if d.status is distinct from 'active' or d.revision is distinct from 'v13' or d.cmd5 <> 'e82427bbc4d5e77bd61db97a7f7f8d22' then
    raise exception 'FSQM-017 is not as this migration expects (%).', d.cmd5;
  end if;
  if d.p->>21 <> $t$• CCP 2 — Vacuum sealing in pouches. Hazard: loss of package integrity, which admits microbial contamination and ends shelf stability. Critical limits: vacuum level to the equipment specification; no visible leak, channel, wrinkle across the seal, or partial seal; and seal width to the equipment specification. Monitoring: the vacuum gauge every cycle, a visual check of every pouch, and a pull test at least hourly and at each set-up.$t$ then raise exception 'FSQM-017 line 21 is not the CCP 2 line.'; end if;
  select status, md5(content::text) as cmd5 into d from public.sop_documents where sop_number = 'FSQM-016';
  if d.status is distinct from 'draft' or d.cmd5 <> '25359d8f89b6fa08825eca2fa308a9c6' then
    raise exception 'FSQM-016 is not the draft this migration expects (%).', d.cmd5;
  end if;
end $guard$;

update public.sop_documents
   set content = jsonb_set(content, '{form_schema}', $q${"sections": [{"id": "day", "title": "1. Production day", "fields": [{"id": "how_this_works", "text": "ONE RECORD PER PRODUCTION DAY, for the product covered by the site's HACCP plan. Fill in the date, the product and the lot code first. Add a row at the first sealing of the run (Set-up), after any change or adjustment to the sealer, and at the end of the run. In process rows may be added at any time. The record stays a draft until the lot has been boxed, when the At boxing rows are added.\n\nCCP 2 PROTECTS THE PRODUCT AFTER THE BAKE. A failed seal lets in air and microbial contamination and ends the product's shelf stability. The critical limits below are the HACCP plan's.\n\nAT SEALING, LOOK AT EVERY POUCH AS IT COMES OFF THE SEALER: the seal sound, and no air in the pouch. That check is the control; the rows record it and do not replace it. Do NOT pull test a pouch that has just been sealed - the film is still warm and a good seal can be pulled open.\n\nAT BOXING, LOOK AT EVERY POUCH AGAIN before it goes in its box. A pouch that has lost its vacuum is rejected. Pull test one cooled pouch from the lot before boxing starts.\n\nA pouch or a pull test that fails stops the work - Section 3 says what happens next.\n\nWHEN BOXING IS DONE, sign Section 4 and leave the entry as a draft. It is reviewed, the verification is signed, and the reviewer submits it.", "type": "info", "label": "Before you start"}, {"id": "production_date", "type": "date", "label": "Production date", "width": "third", "required": true, "showInList": true, "defaultToday": true}, {"id": "product", "help": "The product covered by the HACCP plan.", "type": "text", "label": "Product", "width": "half", "required": true, "showInList": true}, {"id": "lot_code", "type": "text", "label": "Lot / batch code", "width": "half", "required": true, "showInList": true, "help": "Once for the day. It is not entered on each row."}, {"id": "limits", "rows": [["Vacuum level", "To the sealer's specification - NOT YET CONFIRMED for this machine (typical 27 in. Hg)", "The sealer's vacuum gauge", "At set-up"], ["Seal integrity", "No visible leak, channel, wrinkle across the seal, or partial seal, and no air in the pouch", "Visual check", "Every pouch as it comes off the sealer, and again at boxing"], ["Seal width", "To the sealer's specification - NOT YET CONFIRMED for this machine (typical 5 mm)", "Inspection of the seal", "With the pull test"], ["Seal strength", "The seal holds under a pull test", "Pull test on one cooled pouch", "One pouch per lot, at the start of boxing. Never on a warm seal."]], "type": "reference_table", "label": "CCP 2 critical limits (HACCP plan)", "columns": ["Critical limit", "Limit", "How it is checked", "How often"]}]}, {"id": "checks", "title": "2. Sealing checks", "fields": [{"id": "seal_checks", "help": "A row at Set-up, after any change or adjustment, and at the end of the run; In process rows may be added at any time. At boxing: a row for the pull test, and a row when every pouch has been looked at again.", "rows": {"min": 1, "mode": "dynamic", "addLabel": "Add a check"}, "type": "grid", "label": "Sealing checks", "columns": [{"id": "time", "type": "time", "label": "Time", "width": 1, "required": true, "defaultTo": "now"}, {"id": "check", "type": "select", "label": "Check", "width": 2, "options": ["Set-up", "In process", "After a change or adjustment", "End of run", "At boxing"], "required": true}, {"id": "vacuum_reading", "type": "number", "unit": "in. Hg", "label": "Vacuum gauge reading", "width": 1}, {"id": "visual", "type": "pass_fail", "label": "Every pouch since the last row: seal sound, no air in the pouch", "width": 2}, {"id": "pull_test", "type": "pass_fail", "label": "Pull test held (cooled pouch, at boxing)", "width": 1}, {"id": "rejected", "type": "number", "label": "Pouches rejected since the last row", "width": 1}, {"id": "seal_width", "type": "number", "unit": "mm", "label": "Seal width, if measured", "width": 1}, {"id": "initials", "type": "text", "label": "Initials", "width": 1, "required": true, "defaultTo": "currentUserInitials"}, {"id": "note", "type": "text", "label": "Note", "width": 2}], "required": true}, {"id": "spec_info", "text": "The HACCP plan sets the vacuum level and the seal width to the sealer's specification, and gives only typical values (27 in. Hg and 5 mm). Neither has been confirmed for this site's machine. Until it is, write the gauge reading exactly as it shows - this record captures it but cannot show it as within a limit nobody has confirmed. A reading clearly out of line with earlier runs is treated as a failed check.\n\nThe visual check and the pull test ARE judged here, against the limits above.", "type": "info", "label": "Two limits are not yet confirmed"}]}, {"id": "deviation", "title": "3. If a limit was not met", "fields": [{"id": "deviation_info", "text": "A POUCH WITH A SEAL DEFECT OR AIR IN IT, A POUCH THAT HAS LOST ITS VACUUM AT BOXING, OR A FAILED PULL TEST:\n1. Stop sealing or boxing.\n2. Set the failed pouch aside. The pouches before it were each looked at; if there is any doubt about them, put them on Hold and tag them on FRM-702 under FSQM-018. A failed pull test puts the lot on Hold until the SQF Practitioner decides what is done with it.\n3. Re-pouch and reseal what can be resealed, and destroy what cannot.\n4. If the sealer is at fault, inspect or adjust it, then seal a pouch and look at it. Record that as an \"After a change or adjustment\" row before sealing restarts.\n5. Notify the SQF Practitioner, and record the cause and the action on FRM-007 under FSQM-009.\n\nHeld product is not released on FRM-701 until its disposition is recorded.", "type": "info", "label": "What to do"}, {"id": "deviations_today", "type": "select", "label": "Deviations on this day", "width": "half", "options": ["None - every check passed", "Yes - each one is recorded below"], "required": true}, {"id": "deviation_log", "help": "Required for every deviation. Leave empty only where the answer above is None.", "rows": {"min": 0, "mode": "dynamic", "addLabel": "Add a deviation"}, "type": "grid", "label": "Deviations", "columns": [{"id": "time", "type": "time", "label": "Time", "width": 1, "required": true}, {"id": "what", "type": "text", "label": "What failed", "width": 3, "required": true}, {"id": "units_held", "type": "text", "label": "Pouches held", "width": 1}, {"id": "action", "type": "select", "label": "Action taken", "width": 2, "options": ["Resealed", "Held on FRM-702", "Destroyed"], "required": true}, {"id": "reference", "type": "text", "label": "FRM-702 / FRM-007 reference", "width": 2}]}]}, {"id": "signoff", "title": "4. Sign-off", "fields": [{"id": "monitored_by", "role": "filler", "type": "signature", "label": "Monitored by (production operator)", "width": "half", "required": true, "statement": "I looked at every pouch as it came off the sealer and again at boxing, and recorded the checks above as found."}, {"id": "verification_independence", "help": "FSQM-017 Part 5: a person does not verify their own monitoring where a second qualified person is available. Where one is not, say so here.", "type": "select", "label": "Who verified this record", "width": "half", "options": ["Someone other than the operator who took the readings", "No second qualified person available - verified by the operator"], "required": true}, {"id": "verified_by", "role": "verifier", "type": "signature", "label": "Verified by", "width": "half", "required": true, "statement": "I have reviewed this record against the CCP 2 critical limits, and every deviation on it has a recorded action."}]}], "settings": {"deletable": false, "attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{production_date} — CCP 2 Vacuum Sealing"}, "schemaVersion": 1}$q$::jsonb),
       revision = 'v2', effective_date = date '2026-10-07', approved_by = 'GJM'
 where sop_number = 'FRM-606' and status = 'active';

update public.sop_documents
   set content = jsonb_set(jsonb_set(content, '{procedure,21}', to_jsonb($t$• CCP 2 — Vacuum sealing in pouches. Hazard: loss of package integrity, which admits microbial contamination and ends shelf stability. Critical limits: vacuum level to the equipment specification; no visible leak, channel, wrinkle across the seal, or partial seal, and no air in the pouch; and seal width to the equipment specification. Monitoring: a visual check of every pouch as it comes off the sealer, for seal defects and for air in the pouch. At boxing, once the seal is cool, every pouch is looked at again for lost vacuum and one pouch from each lot is pull tested. A pull test is not done on a warm seal.$t$::text)),
                           '{revision_history}', to_jsonb((content->>'revision_history') || E'\n\n' || $t$v14 — 2026-10-07 — CCP 2 monitoring stated as it is performed. Management's decision: every pouch is looked at as it comes off the sealer, for seal defects and for air in the pouch; at boxing, once the seal is cool, every pouch is looked at again and one pouch from each lot is pull tested. The June 2026 plan's hourly pull test at the sealer is withdrawn - a warm seal can be pulled open by the test itself - and so is its gauge check on every cycle, which was not being performed. Recorded on FRM-606 v2. The record, the weekly review and the schedule are unchanged.$t$)),
       revision = 'v14', effective_date = date '2026-10-07', approved_by = 'GJM'
 where sop_number = 'FSQM-017' and status = 'active';

update public.sop_documents
   set content = content || $q${"procedure": ["Scope", "> The plan starts at the receipt of ingredients and packaging and ends when finished product is collected by the customer's carrier. Every input and output in between - raw materials, packaging, service inputs, the two overnight delays, waste and rework - is shown on the flow diagram in Attachment A (SQF 2.4.3.3).", "Product description", "• Product: rum cake, in several flavours, made for Bahamas Rum Cake Factory. A shelf-stable baked product, stored and distributed at ambient temperature.", "• Composition: cake mix (containing wheat flour, sugar and nonfat dry milk), liquid whole eggs, soybean oil, water and flavour emulsion; the molds are sprayed with a pan release of soybean oil and soy lecithin before depositing; after baking, dipped in a syrup of water, sugar and rum.", "• Allergens: wheat, milk, egg and soy, as declared on each flavour's approved label.", "• Packaging: vacuum-sealed pouch in a baking cup, in an individual product box; boxes packed in coded master cases, palletized and stretch wrapped.", "• Shelf life: 12 months, printed on the pack as a Best By month and year.", "• Water activity and pH: not yet measured.", "> Each flavour's finished product specification is its entry on FRM-704, which this description refers to (SQF 2.4.3.4). The product is called shelf stable because of reduced water activity, but that figure has not been measured, and the syrup added after baking returns water and sugar to the product. Part 7 has therefore been written with growth in the sealed product scored as significant. The water activity of the finished, sealed product is recorded here when it has been measured, and that line of Part 7 is then scored again.", "Intended use", "• Ready to eat; no further cooking by the consumer.", "• General public. The product contains rum. The June 2026 plan cautioned against its use by immunocompromised individuals, infants and pregnant women without physician guidance; the food safety team is to confirm that caution and the vulnerable groups it names (SQF 2.4.3.5).", "Food safety team", "• SQF Practitioner - leads the team. Brings the production process, the equipment and the CCP monitoring as they are performed on the floor.", "• Senior Site Manager - substitute SQF Practitioner. Brings the product, its formulation, raw materials and packaging, and approves this plan.", "• Engineering knowledge is not held on the team. It is taken from the equipment manufacturers' manuals and their service technicians, and the source is named wherever this plan relies on it (SQF 2.4.3.2).", "• Who holds each position is recorded on FRM-005 and in FSQM-004, not here, so that this plan does not have to be reissued when a person changes.", "• The team meets as each remaining Part of this plan is written, and afterwards at least annually for the full review and whenever a change requires one (Part 9). Its decisions are recorded by revising this plan, and the annual review is also recorded on FRM-001.", "> HACCP TRAINING - NOT YET HELD. No member of the team holds a HACCP training certificate. SQF 2.1.1.5 requires the SQF Practitioner to have completed HACCP training, and an auditor checks for it here first. The SQF Practitioner and the Senior Site Manager are each to complete a HACCP course; each certificate is filed on FRM-952 and this Part revised to say so. Until then the team meets 2.4.3.2 in its membership but cannot yet show the competence it asks for.", "Process flow diagram", "• The flow diagram is Attachment A. It shows every step from receipt to dispatch across the three days, every raw material, packaging item and service input, the two scheduled overnight delays, and every output including waste and the one rework loop.", "• The food safety team confirms it once, by walking the floor on all three days of the rotation so that every step is seen as it is performed, and then dates and signs the confirmation block on the diagram one time. That signed block is the confirmation SQF 2.4.3.6 requires. It is not signed daily.", "• The diagram is re-confirmed whenever the process, equipment or rotation changes, and at the annual review of this plan.", "> FSQM-039 Facility Layout and Product Flow shows where equipment stands and where product goes on the floor. It is not this flow diagram and is not offered as one.", "Hazard significance methodology", "• Name every hazard specifically and type it as biological, chemical (allergens included) or physical: Salmonella, not \"pathogens\"; hard or sharp foreign material from a named source, not \"foreign material\".", "• LIKELIHOOD, judged as if the step's own control measure were absent:", "◦ 1 = Unlikely: no record of it for this material or process, in the industry or at the site.", "◦ 2 = Possible: known to occur in the industry for this kind of material or process.", "◦ 3 = Likely: has occurred at this site, or is expected without control.", "• SEVERITY, the worst harm a consumer could reasonably suffer:", "◦ 1 = Low: brief discomfort, no lasting effect.", "◦ 2 = Moderate: illness or injury needing treatment, without lasting harm.", "◦ 3 = High: serious illness or injury, hospitalisation or death.", "• ALWAYS SEVERITY 3: an undeclared allergen; a pathogen such as Salmonella or Listeria monocytogenes; hard or sharp foreign material 7 mm to 25 mm long.", "• SCORE = likelihood × severity. 6 or 9 = SIGNIFICANT. 1 to 4 = not significant, and the analysis records why.", "• EVIDENCE FOR \"UNLIKELY\": a severity 3 hazard scored as unlikely (a score of 3) records the evidence that makes it unlikely. \"Unlikely\" cannot be asserted without it.", "> WHY THE STEP'S OWN CONTROL IS SET ASIDE. A hazard is judged as if the control at that step were not there. Otherwise every hazard the site already controls would score as unlikely and not significant, and the analysis would conclude that nothing needs controlling. A prerequisite program that is documented, implemented and verified - supplier approval, GMP, sanitation, pest control - may be counted when judging likelihood, and the analysis names the program it relies on.", "> Evidence for a likelihood or severity score comes from the FDA's Hazard Analysis and Risk-Based Preventive Controls for Human Food guidance (its appendix of hazards by ingredient and process), product recalls and outbreaks involving similar products, supplier information, and this site's own records of complaints, holds and deviations.", "• Every significant hazard is given a control measure in Part 7 and is taken through the CCP decision in Part 8. Every hazard that is not significant is recorded with the reason and the prerequisite program that keeps it so.", "• Each row of the analysis records the step, the hazard, its type and source, the likelihood, severity and score, whether it is significant, the justification, and the control measure.", "> This method is applied in exactly the same way to every hazard at every step (SQF 2.4.3.8). It is changed only by revising this Part, and a change to it means every hazard in Part 7 is scored again.", "Hazard analysis and control measures", "> This Part applies the method in Part 6 to every step on Attachment A. Each line under a step is one hazard: its type (B biological, C chemical including allergens, P physical), what it is and where it comes from, likelihood × severity = score, whether it is significant, why, and the control measure. Likelihood is judged as if the step's own control were absent (SQF 2.4.3.7 to 2.4.3.9).", "> THE SCORES BELOW ARE THE DRAFT PUT TO THE FOOD SAFETY TEAM. The team checks every line against the floor and adopts or changes it before this plan is issued.", "• STEP 1 - Receive ingredients and packaging.", "◦ B - Salmonella and Shiga toxin-producing E. coli in the cake mix (wheat flour, nonfat dry milk): L2 × S3 = 6, SIGNIFICANT. Flour is milled from raw grain and is not treated to kill pathogens; flour and dry mixes have caused outbreaks and recalls, and milk powder is a known Salmonella vehicle. Control: the bake at step 7.", "◦ B - Salmonella in the liquid whole egg: L2 × S3 = 6, SIGNIFICANT. Liquid egg is normally sold pasteurised, but Salmonella survives a failed pasteurisation and grows if the cold chain fails. Control: supplier approval (SOP-2.3.4, FRM-202), receipt at 41°F or below recorded on FRM-301 (FSQM-035), and the bake at step 7.", "◦ C - An allergen that is not on the finished product's label, arriving in an ingredient: a supplier changes a recipe, or a different brand is bought in place of the usual one. L2 × S3 = 6, SIGNIFICANT. The ingredients are bought from cash-and-carry suppliers, where the brand on the shelf can change. Control: each material's declaration is recorded word for word from its pack on FRM-207, and the brand received is recorded on FRM-301.", "◦ C - Mycotoxins and pesticide residues in the wheat flour and sugar: L1 × S2 = 2, not significant. Regulated at the mill and the refinery; no history at the site. Kept so by supplier approval (SOP-2.3.4).", "◦ P - Hard or sharp foreign material (metal, glass, stone, hard plastic) in an ingredient as received: L2 × S3 = 6, SIGNIFICANT. It is known to occur in bagged dry ingredients, and the site holds no supplier evidence that would make it unlikely. Control: NONE AT THIS SITE TODAY - there is no sieve, magnet or metal detector (FSQM-013). See the findings below.", "◦ C - Food-contact packaging (vacuum pouches, baking cups) that is not suitable for food: L1 × S2 = 2, not significant. Kept so by the packaging specifications on FRM-207; the suppliers' letters of guarantee are still to be obtained.", "• STEP 2 - Store: dry goods at ambient temperature, liquid eggs refrigerated.", "◦ B - Salmonella growing in liquid egg held above 41°F: L2 × S3 = 6, SIGNIFICANT. Control: the walk-in is monitored continuously, with alerts (SOP-401, FRM-401); the bake at step 7.", "◦ C - An allergen that is not on this product's label, from another product's ingredients stored on site: L2 × S3 = 6, SIGNIFICANT. Control: allergen ingredients are kept sealed on their own labelled rack and never above other ingredients (FSQM-035).", "◦ C - Cleaning chemicals contaminating stored ingredients or packaging: L1 × S2 = 2, not significant. Chemicals are kept in the locked locker, away from ingredients and packaging (FSQM-032, FSQM-035).", "◦ B, P - Contamination by pests: L2 × S2 = 4, not significant. Kept so by FSQM-031 and by sealed containers.", "• STEP 3 - Weigh and measure ingredients, including water.", "◦ B - Pathogens from hands, utensils or the bench into the ingredients: L2 × S3 = 6, SIGNIFICANT. Control: the bake at step 7; handwashing and illness rules (FSQM-012); the pre-operation check (FRM-903).", "◦ B, C - Contaminated water used as an ingredient: L1 × S3 = 3, not significant. Evidence: the City of Sanford's treated supply and its annual water quality report (FRM-915), and the water is then baked. FSQM-033 is still a draft and the site's own yearly test has not yet been done.", "◦ P - Pieces of ingredient packaging (paper, film, thread) falling in when a bag is opened: L2 × S2 = 4, not significant. Soft, not hard or sharp. Kept so by GMP (FSQM-012).", "• STEP 4 - Mix batter.", "◦ P - Metal from the mixer bowl, the agitator or a loose part: L2 × S3 = 6, SIGNIFICANT. Control: the mixer is checked clean, complete and with nothing left on it before use (FRM-909) and is on the monthly maintenance check (FSQM-029, FRM-508). There is no detection step after it - see the findings below.", "◦ C - An allergen that is not on this product's label, left on the mixer by a different product: L2 × S3 = 6, SIGNIFICANT. Control: the allergen changeover clean and inspection (SOP-901), recorded on FRM-909.", "◦ C - Detergent, sanitizer or lubricant left on the mixer: L1 × S2 = 2, not significant. The sanitizer is made up to its no-rinse food-contact strength and read with a test strip (SOP-901, FSQM-032).", "◦ B - Staphylococcus aureus growing and forming toxin in batter left standing: L1 × S2 = 2, not significant. All batter is deposited and baked on the day it is mixed.", "• STEP 5 - Spray molds with pan release.", "◦ C - Soy, from the soy lecithin in the pan spray: present by design and declared on the label, so it is not scored here. A change of pan spray is the ingredient hazard at step 1.", "◦ P - Fragments from a chipped, cracked or flaking mold: L1 × S3 = 3, not significant. Evidence: every mold is checked before each use and inspected at each wash, and a damaged mold is taken out of service (SOP-906, FRM-903).", "• STEP 6 - Deposit batter into the sprayed molds.", "◦ P - Metal, hard plastic, a seal or an O-ring from the depositor: L2 × S3 = 6, SIGNIFICANT. Control: the depositor is checked at reassembly and before use (FRM-910, FRM-911) and is on the monthly maintenance check (FSQM-029). There is no detection step after it - see the findings below.", "◦ C - An allergen left on the depositor by a different product: as for the mixer at step 4, SIGNIFICANT. Control: the allergen changeover clean (SOP-902, SOP-903), recorded on FRM-910 or FRM-911.", "• STEP 7 - Bake.", "◦ B - Salmonella, Shiga toxin-producing E. coli and Listeria monocytogenes from the flour, egg and milk powder surviving the bake: L3 × S3 = 9, SIGNIFICANT. They are expected in raw batter and this is the only step that kills them. Control: oven at 350°F or above for at least 27 minutes, recorded for every load on FRM-507. These limits are carried from the June 2026 plan and have not been validated for this product in this oven, and the product's internal temperature is not measured - see the findings below.", "◦ B - Spores of Bacillus cereus and Clostridium species from the flour, sugar and milk powder surviving the bake: L3 × S2 = 6, SIGNIFICANT. Baking does not kill spores; they are a hazard only if they can grow afterwards. Control: none at this step. Growth is prevented by the water activity of the finished product, which has not been measured - see step 13.", "◦ C - Acrylamide formed in baking: L2 × S1 = 2, not significant. A long-term dietary concern, not an acute one, at a normal bake colour.", "• STEP 8 - Remove from the oven and cool in the pans, covered, at room temperature.", "◦ B - Salmonella or Listeria monocytogenes reaching the baked product from racks, covers, hands or the room: L2 × S3 = 6, SIGNIFICANT. The product is ready to eat from here on, and nothing later kills what lands on it. Control: sanitation and the pre-operation release (FRM-903, FRM-902), GMP (FSQM-012) and the hygiene zoning of the cooling area (FSQM-039). The environmental monitoring that would verify this (FSQM-015) is still a draft.", "◦ B - Spores that survived the bake growing while the product cools: L2 × S2 = 4, not significant, PROVISIONAL. The cooling time is not limited - depanning may follow later the same day or the next day - and whether spores can grow in the baked product depends on its water activity, which has not been measured.", "• STEP 9 - Depan.", "◦ B - Staphylococcus aureus, norovirus or Salmonella from hands onto ready-to-eat product: L2 × S3 = 6, SIGNIFICANT. Control: handwashing, gloves and the illness and wound rules (FSQM-012), checked on the GMP inspection (FRM-913).", "• STEP 10 - Prepare dipping syrup, only when none is in stock.", "◦ B - Pathogens in the sugar, water or rum: L1 × S3 = 3, not significant. Evidence: refined sugar, treated city water and distilled spirit are not known vehicles for Salmonella, and the sugar and water are heated in the kettle before the rum is added. The temperature reached is not recorded.", "◦ B - Yeasts, molds or bacteria growing in syrup kept for a later run: L2 × S2 = 4, not significant. The syrup is two parts sugar to one part water, with rum added: a concentrated sugar syrup with alcohol, in which food-poisoning bacteria are not expected to grow. Its own water activity has not been measured and the amount of rum is not recorded here. Kept so by the hold rule below.", "◦ SYRUP HOLD RULE. Prepared syrup is kept sealed, at room temperature, for no more than 30 days from the day it was made; it is normally used within a few days. The container is labelled with the date made and a lot code in the same form as the product's - the last digit of the year and the three-digit day of the year. Syrup that is past 30 days, unlabelled, or showing gas, cloudiness, mold or an off smell is discarded.", "◦ P - Fragments from the kettle or utensils: L1 × S3 = 3, not significant. Evidence: the kettle is cleaned and checked before use (SOP-904, FRM-912).", "• STEP 11 - Dip the baked product in syrup at room temperature.", "◦ B - Pathogens carried onto ready-to-eat product by the syrup, the dip container, utensils or hands: L2 × S3 = 6, SIGNIFICANT. This is a wet step after the only kill step. Control: the changeover clean of the dunk bay before Day 2 and its pre-operation release (FRM-903); GMP (FSQM-012); the syrup hold rule at step 10.", "◦ B - The syrup adds water back to the baked product. Its effect on growth in the finished product is scored at step 13.", "• STEP 12 - Place in baking cups.", "◦ B - Hand contact with ready-to-eat product: as step 9, SIGNIFICANT, with the same control.", "• STEP 13 - Vacuum seal.", "◦ B - Clostridium botulinum or Staphylococcus aureus growing in the sealed product during up to twelve months at room temperature: L2 × S3 = 6, SIGNIFICANT UNTIL THE WATER ACTIVITY IS MEASURED. A vacuum pouch removes air, which favours C. botulinum, and the product is kept unrefrigerated. Below a water activity of 0.85 no food-poisoning bacteria grow, and the product is believed to be below it; but Part 6 does not allow a severity 3 hazard to be called unlikely without evidence, and there is none. Control: the product's formulation - its sugar and rum - which becomes a stated control with a limit once the water activity of the finished, sealed product has been measured.", "◦ B - Contamination or mold growth through a leaking, channelled or partial seal: L2 × S2 = 4, not significant by this method. Every pouch is looked at as it comes off the sealer, for a leak, channel, wrinkle or partial seal and for air in the pouch, and is looked at again at boxing. Recorded on FRM-606.", "◦ REWORK - a pouch that fails is opened and the product re-pouched. The hand-contact hazard of step 9 applies, with the same control.", "• STEPS 14 TO 17 - Box; label, lot code and best-by date; pack and code master cases; palletize and stretch wrap.", "◦ C - The wrong label or box, or a label that does not declare wheat, milk, egg and soy: L2 × S3 = 6, SIGNIFICANT. Control: labels are approved on FRM-601 (SOP-2.3.2.3), and the label applied is checked against the approved label at release on FRM-701 (FSQM-020).", "◦ CCP 2 CHECK AT BOXING - before a pouch goes in its box it is looked at again, and a pouch that has lost its vacuum is rejected. One cooled pouch from each lot is pull tested before boxing starts. The pull test is not done at sealing: the film is still warm then, and a good seal can be pulled open. Recorded on FRM-606.", "◦ C - Coder ink: L1 × S1 = 1, not significant. It is applied to the outside of the box and the case only, never to a food-contact surface.", "• STEP 18 - Release check.", "◦ No hazard is introduced. The check on FRM-701 is itself a control: no batch leaves under an open hold, without its pre-operation release recorded, or with a label that is not the approved one (FSQM-020).", "• STEPS 19 AND 20 - Warehouse storage at ambient temperature, and dispatch.", "◦ B - Growth in the sealed product over its shelf life: scored at step 13.", "◦ B, P - Pests or handling damaging packs: L1 × S2 = 2, not significant. Kept so by FSQM-031, FSQM-035 and the loading check on FRM-801 (FSQM-036).", "• AT EVERY STEP.", "◦ P - Glass or brittle plastic from lights, gauges or fittings: L1 × S3 = 3, not significant. Evidence: every item is on the register and checked (SOP-11.7.3, FRM-907), and a breakage is handled on FRM-908.", "◦ P - Jewellery, pens, dressings and other personal items: L1 × S2 = 2, not significant. Kept so by FSQM-012.", "◦ C - Sanitizer or detergent on a food-contact surface at the wrong strength: L2 × S2 = 4, not significant. The strength is read with a test strip and recorded (FRM-903, FSQM-032).", "◦ Compressed air, ice and steam do not contact the product (FSQM-013), so no hazard arises from them.", "> WHAT THIS ANALYSIS FINDS. Four of the significant hazards above do not yet have a control that is in place and proven, and this plan cannot be issued as complete until each is settled.", "• WATER ACTIVITY. Whether pathogens can grow in the finished product is not known, because its water activity has never been measured. The measurement that decides it is of the product as sold - after the dip, sealed, and left a day or more to settle - and not of the cake before it is dipped: the syrup puts water back, and the sealed pack is what sits at room temperature for a year. Water activity is not wetness; sugar and alcohol hold water so that microbes cannot use it, which is why a syrup-soaked cake can still measure low.", "• FOREIGN MATERIAL. Hard or sharp foreign material is a significant hazard at steps 1, 4 and 6, and nothing in the process would find it. The metal detector named in FSQM-013 Part 5 is the planned control; until it is installed and its limits are set, the pre-use equipment checks are the only measure.", "• THE BAKE. The limits of 350°F and 27 minutes have not been validated against this product in this oven, and the internal temperature is not measured. Validation is workbook tasks 14.7 to 14.9.", "• AFTER THE BAKE. Recontamination of ready-to-eat product at steps 8 to 12 is controlled by cleaning and hygiene alone. Environmental monitoring (FSQM-015) is what would show that this control works, and it is not yet in force.", "> Part 8 takes each significant hazard through the CCP decision. Two results of this analysis bear on it. The failed-seal hazard at step 13 scores as not significant, so the team must decide whether vacuum sealing remains a critical control point. And if water activity proves to be the control for growth, its limit belongs in Part 8.", "Critical control points", "> Every significant hazard in Part 7 is taken through the four questions of the Codex decision tree, in the same way each time (SQF 2.4.3.10). THE DECISIONS BELOW ARE THE DRAFT PUT TO THE FOOD SAFETY TEAM, as Part 7 is.", "• THE FOUR QUESTIONS, asked of each significant hazard at the step where it arises:", "◦ Question 1 - Do the prerequisite programs control it at this step? If yes, it is not a CCP. A program counts only when it is issued, in use and verified (Part 6).", "◦ Question 2 - Is there a control measure for it at this step? If there is none and control is needed for safety, the step, the process or the product has to change.", "◦ Question 3 - Will a later step remove it or bring it down to a safe level? If yes, that later step is where it is controlled.", "◦ Question 4 - Does this step remove it or bring it down to a safe level? If yes, this step is a CCP.", "• THE DECISIONS:", "◦ Pathogens in the cake mix and the liquid egg, their growth in egg held too warm, and pathogens from hands into the ingredients (steps 1, 2 and 3): Question 1 no - supplier approval, cold storage and GMP lower them but do not remove them. Question 3 yes - the bake. NOT A CCP at these steps; controlled at CCP 1.", "◦ Pathogens surviving the bake (step 7): Question 1 no. Question 2 yes. Question 3 no - nothing after the oven kills. Question 4 yes. CCP 1.", "◦ Spores surviving the bake (step 7), and Clostridium botulinum or Staphylococcus aureus growing in the sealed product (step 13): baking does not kill spores, so the only control is that the finished product cannot support growth. Question 2 cannot be answered until the water activity of the finished, sealed product is measured. NOT YET DECIDED. If it is 0.85 or below, the recipe and the dip that give that figure become a control with a limit, written here. If it is above, the product or the process has to change.", "◦ An undeclared allergen arriving in an ingredient, or from another product's ingredients in storage (steps 1 and 2): Question 1 yes - the material declarations on FRM-207, the brand check at receipt on FRM-301 and segregated storage (FSQM-027, FSQM-035). NOT A CCP.", "◦ An allergen left on the mixer or a depositor by a different product (steps 4 and 6): Question 1 yes - the changeover clean, checked and swabbed (FSQM-027, SOP-901 to SOP-903, FRM-916). NOT A CCP.", "◦ Hard or sharp foreign material in an ingredient, or metal from the mixer or a depositor (steps 1, 4 and 6): Question 1 no - the checks before use lower it but would not find it. Question 2 no - there is no control measure. THE PROCESS HAS TO CHANGE. Management's decision, 2026-10-07: a metal detector, not yet bought. When it is installed it becomes a CCP, with its limits and test pieces set when it is commissioned. A metal detector finds metal only: the team decides, with evidence from the suppliers, whether stone, glass and hard plastic in the dry ingredients are unlikely, or whether those ingredients are also sieved.", "◦ Recontamination of the baked product from surfaces, the room, the syrup or hands (steps 8, 9, 11 and 12): Question 1 yes - cleaning and the pre-operation release (FRM-903), GMP (FSQM-012) and the zoning (FSQM-039), with environmental monitoring (FSQM-015) to show they work. NOT A CCP: there is no later kill step, and nothing at these steps can be measured against a limit for each batch.", "◦ The wrong label, or a label that does not declare the allergens (steps 14 to 17): Question 1 yes - label approval on FRM-601 and the label check at release on FRM-701 (FSQM-020). NOT A CCP.", "• THE CRITICAL CONTROL POINTS:", "◦ CCP 1 - Baking (step 7): oven at least 350°F for at least 27 minutes, recorded on FRM-507 CCP 1 Baking Monitoring Record. The June 2026 plan also sets an internal temperature of at least 180°F at the end of the bake; the product is not probed today, and FRM-507 records that.", "◦ CCP 2 - Vacuum sealing (step 13): every pouch sealed intact with no leak, channel, wrinkle or partial seal and no air in the pouch. Every pouch is looked at as it comes off the sealer and again at boxing, where one cooled pouch from each lot is pull tested. Recorded on FRM-606 CCP 2 Vacuum Sealing Monitoring Record. The vacuum level and seal width for the site's machine are not yet confirmed.", "• CCP 2 IS KEPT, ALTHOUGH THE METHOD DOES NOT REQUIRE IT. A failed seal scores as not significant in Part 7, so the questions above would not make sealing a CCP. Management's decision, 2026-10-07: it stays a CCP, monitored and recorded as now, until the water activity is known and the team has HACCP training. It is decided again then.", "• CCP 1 is checked and recorded for every oven load. For CCP 2 every pouch is looked at, and a row is recorded at the first sealing, after any adjustment, at the end of the run and at boxing (SQF 2.4.3.12).", "• A failed limit stops the step. The affected product is held on FRM-702 and dispositioned under FSQM-018, and the cause is corrected under FSQM-009 on FRM-007 (SQF 2.4.3.13).", "• NOT YET IN PLACE, and this plan cannot be issued as complete until each is:", "◦ The critical limits of CCP 1 are not validated for this product in this oven (SQF 2.4.3.11).", "◦ The water activity is not measured, so growth in the sealed product has no decided control.", "◦ There is no metal detector.", "◦ FSQM-027 and FSQM-015 are still drafts. The decisions above that rest on them hold only once they are issued and in use.", "◦ No member of the team holds HACCP training (Part 4), so these decisions have not yet been made by a trained team.", "Verification and review", "• The CCP records are reviewed and signed weekly under FSQM-017 (SQF 2.4.3.15 and 2.4.3.16).", "• The food safety team reviews this plan in full at least annually, and whenever the product, ingredients, process, equipment or packaging changes in a way that could affect food safety (SQF 2.4.3.14 and 2.3.1.3)."], "revision_history": "New - 2026-09-21 - DRAFT, under D-14. Created so the rebuilt plan has a controlled home while it is written, and so the flow diagram (task 14.2) can be attached to it as Attachment A.\n\nWHAT IS WRITTEN: scope, product description, intended use, the flow diagram Part, the CCPs as they are monitored today, and verification.\n\nWHAT IS NOT: Parts 4, 6 and 7 are marked NOT YET WRITTEN and name the workbook task that writes each. A plan that read as complete before its hazard analysis existed would be the defect the gap assessment found, repeated.\n\nThe number FSQM-016 was reserved for this plan in the remediation workbook on 2026-09-04, after FSQM-013 went to the Module 11 exemption analysis.\n\nNew (draft) - 2026-09-21 - Part 4 written (workbook task 14.1). The team is two positions, SQF Practitioner and Senior Site Manager, with engineering advice taken from equipment manufacturers. Positions are named, not people. Neither member holds a HACCP certificate yet, and Part 4 says so rather than implying a qualified team.\n\nNew (draft) - 2026-09-21 - Part 6 written (workbook task 14.4): a three-by-three likelihood and severity method, significant at a score of 6 or more, with fixed severity-3 hazards, evidence required for any severity-3 hazard called unlikely, and the step's own control set aside when judging likelihood. It is written before the hazard analysis because the gap assessment's finding against 2.4.3.8 was inconsistency, not absence.\n\nNew (draft) - 2026-09-21 - Part 6 re-laid out, wording unchanged in substance: each scale on one line with its levels numbered inline, and the fixed severity-3 hazards, the score rule and the evidence rule each on their own line. The body renders one list level only, so the scale levels had appeared as bullets alongside the rules they belong to.\n\nNew (draft) - 2026-09-21 - Part 6's likelihood and severity levels each on their own indented line, using the new sub-item line form (a line opening with the white bullet sits one level in under the bullet above it). Wording unchanged.\n\nNew (draft) - 2026-09-28 - ATTACHMENT A CORRECTED IN FIVE PLACES, found while the owner and the Senior Site Manager read the flow against the process.\n\n1. THE PAN RELEASE IS ITS OWN STEP. The molds are sprayed with Chef's Quality Pan Spray (soybean oil and soy lecithin) before the batter is deposited; the drawing had shown it only as an unnamed input to depositing. It is now step 5, 'Spray molds with pan release - done before, after or alongside mixing', which is how it is performed, and step 6 deposits into sprayed molds. The composition above names it.\n\n2. COOLING COMES BEFORE DEPANNING. The drawing had the product depanned as it left the oven. In fact the pans go straight onto the cooling racks and the product is turned out once it is cool. Day 1 now ends at 'Remove from oven, place the pans on the cooling racks', and Day 2 opens with step 9, 'Depan - turn the cooled product out of the pans'.\n\n3. THE COOL IS NOT NECESSARILY OVERNIGHT. Gabriela, 2026-09-28: what is required is cooling before depanning, and some batches are depanned later on Day 1 and some on Day 2. The delay now reads 'cool in the pans, covered, at room temperature on the racks, until cool enough to depan', with a note that depanning follows later on Day 1 or on Day 2. Writing it as a fixed overnight delay would have stated a control the site does not work to.\n\n4. MAKING THE SYRUP IS A CONDITIONAL STEP. Syrup is not made every run: step 10 runs only when no prepared syrup is in stock. Syrup kept for a later run is held ambient in a sealed container, and the dip step takes prepared syrup from stock as an input.\n\n5. THE SYRUP IS DIPPED AT ROOM TEMPERATURE. Syrup made on the day is cooled to room temperature before use, which the drawing carries as a delay off step 10; syrup taken from stock is already at room temperature. Step 11 reads 'Dip baked product in syrup at room temperature'. This matters to the hazard analysis in both directions: hot syrup on baked product is a different step from what the site performs, and a syrup cooling on the bench is itself a delay to be assessed.\n\nOPEN, AND ON THE DRAWING AS A GAP: stored syrup has NO HOLD LIMIT and NO LABEL today. How long it may be held, and what the container says, are decided in the hazard analysis (Part 7). A held food component with neither a limit nor a date is both a food safety question and a traceability one - a dipped batch cannot be tied to the syrup it was dipped in.\n\nThe diagram is now 20 steps. CCP 1 baking stays step 7; CCP 2 vacuum sealing moves from step 11 to step 13, and the scope box's rework sentence moved with it.\n\nALLERGEN: the spray's label declares CONTAINS: SOY, from the soy lecithin. Soy was already declared as an allergen of this product, and the owner confirmed on 2026-09-28 that the finished product label declares it, so nothing about the declaration changes. The pan spray and the bulk soybean oil are separate FRM-207 entries and are separate materials.\n\nTHIS IS WHAT CONFIRMING A FLOW DIAGRAM IS FOR (SQF 2.4.3.6): two things the drawing showed differently from how the floor works. The confirmation block on Attachment A is signed against this version, not the one before it.\n\nNew (draft) - 2026-10-01 - PART 7 WRITTEN (workbook tasks 14.5 and 14.6): the hazard analysis, step by step against the confirmed 20-step flow diagram, scored by the method in Part 6. With it every Part of this plan has text; none is marked NOT YET WRITTEN.\n\nIT IS A DRAFT FOR THE FOOD SAFETY TEAM, NOT THE TEAM'S ANALYSIS. The hazards, scores and controls were drafted from the flow diagram, the site's issued programs and what the site has said about its process. The team checks each line against the floor and adopts or changes it. No member of the team yet holds HACCP training (Part 4).\n\nWRITTEN BEFORE THE WATER ACTIVITY IS KNOWN. The product description had said the water activity was to be recorded before Part 7 was written. It has not been measured, so growth in the sealed product is scored as significant, as Part 6 requires of a severity 3 hazard with no evidence. The measurement needed is of the finished, sealed product - not of the cake before it is dipped.\n\nSYRUP (site, 2026-10-01): made two parts sugar to one part water, with rum added after heating; normally used within a few days; a hold limit of 30 days is set, sealed at room temperature; the container carries the date made and a lot code in the product's form. This closes the gap carried on the drawing since 2026-09-28. A supplier's specification for an invert syrup, giving six months in its original sealed packaging, was offered as the basis for a longer hold and was not used: it describes a different product in a different pack.\n\nWHAT THE ANALYSIS FOUND: four significant hazards without a control that is in place and proven - growth in the sealed product (water activity unmeasured), hard or sharp foreign material (no detection; a metal detector is planned), the bake (limits not validated, internal temperature not measured), and recontamination after the bake (environmental monitoring not in force). It also scores a failed seal as not significant, which puts CCP 2 in question for Part 8.\n\nOPEN BEFORE ISSUE: (1) the water activity, and pH, of the finished sealed product; (2) the team's review of every line; (3) which allergens other than wheat, milk, egg and soy are on the site; (4) that the liquid egg is pasteurised, from its pack - FRM-207 holds four materials so far; (5) whether a delivery of a brand that is not the one on FRM-207 is held until it has been checked - nothing requires it today; (6) the syrup: how much rum goes in, whether syrup already used for dipping may be kept, and writing the syrup's lot code on the lot record (FRM-520) of each batch dipped in it; the 30 days is the site's limit, not a measured one; (7) the metal detector; (8) validation of the bake; (9) FSQM-015; (10) the CCP decision in Part 8.\n\nNew (draft) - 2026-10-07 - PART 8 WRITTEN AS A DRAFT (workbook task 14.7): each significant hazard taken through the four questions of the Codex decision tree. CCP 1 baking stands. By the method sealing would not be a CCP; management keeps it as CCP 2 until the water activity is known and the team is trained. Foreign material has no control, so the process has to change: management's decision is a metal detector, not yet bought, which becomes a CCP when it is installed. Growth in the sealed product is not decided until the water activity is measured. Allergens, recontamination after the bake and labelling are controlled by programs and are not CCPs; two of those programs, FSQM-027 and FSQM-015, are still drafts. No member of the team holds HACCP training, so this is a draft for a trained team to confirm.\n\nNew (draft) - 2026-10-07 - CCP 2 wording corrected to what is done (site, 2026-10-07): every pouch is looked at as it comes off the sealer and again at boxing; the pull test is on one cooled pouch per lot at boxing, never on a warm seal; the gauge is read at set-up. The earlier text said every pouch was pull tested."}$q$::jsonb
 where sop_number = 'FSQM-016' and status = 'draft';

do $verify$
declare d record; sc jsonb; g jsonb;
begin
  select status, revision, approved_by, effective_date, content into d from public.sop_documents where sop_number = 'FRM-606';
  if d.status <> 'active' or d.revision <> 'v2' or d.approved_by <> 'GJM' or d.effective_date <> date '2026-10-07' then
    raise exception 'FRM-606 was not issued as v2.';
  end if;
  sc := d.content->'form_schema';
  g := sc->'sections'->1->'fields'->0;
  if (select count(*) from jsonb_array_elements(sc->'sections') s, jsonb_array_elements(s->'fields') x) <> 13
     or sc->'sections'->0->'fields'->3->>'id' <> 'lot_code' or (sc->'sections'->0->'fields'->3->>'required')::boolean is not true then
    raise exception 'FRM-606 does not carry the lot code once at the top.';
  end if;
  if exists (select 1 from jsonb_array_elements(sc->'sections') s, jsonb_array_elements(s->'fields') x,
                           jsonb_array_elements(coalesce(x->'columns', '[]'::jsonb)) c where jsonb_typeof(c) = 'object' and c->>'id' = 'lot_code') then
    raise exception 'a grid on FRM-606 still asks for the lot code on every row.';
  end if;
  if (g->'columns'->1->'options') <> '["Set-up", "In process", "After a change or adjustment", "End of run", "At boxing"]'::jsonb
     or jsonb_array_length(g->'columns') <> 9
     or (select count(*) from jsonb_array_elements(g->'columns') c where c->>'id' in ('vacuum_reading', 'visual', 'pull_test') and c ? 'required') <> 0
     or (select count(*) from jsonb_array_elements(g->'columns') c where c->>'id' in ('time', 'check', 'initials') and (c->>'required')::boolean) <> 3 then
    raise exception 'FRM-606 sealing grid is not as intended.';
  end if;
  if d.content::text ~* 'every hour|at least hourly|EVERY CYCLE|last check that passed|"Hourly"' then
    raise exception 'FRM-606 still states a check that is not performed.';
  end if;
  if not exists (select 1 from public.sop_document_history h join public.sop_documents x on x.id = h.document_id
                  where x.sop_number = 'FRM-606' and h.revision = 'New') then
    raise exception 'FRM-606 revision New was not snapshotted.';
  end if;

  select status, revision, approved_by, effective_date, content into d from public.sop_documents where sop_number = 'FSQM-017';
  if d.status <> 'active' or d.revision <> 'v14' or d.approved_by <> 'GJM' or d.effective_date <> date '2026-10-07' then
    raise exception 'FSQM-017 was not issued as v14.';
  end if;
  if d.content->'procedure'->>21 like '%hourly%' or d.content->'procedure'->>21 like '%every cycle%'
     or d.content->'procedure'->>21 not like '• CCP 2 — Vacuum sealing in pouches.%'
     or d.content->'procedure'->>21 not like '%not done on a warm seal%'
     or d.content->>'revision_history' not like '%v14 — 2026-10-07%' then
    raise exception 'FSQM-017 line 21 or its revision note is wrong.';
  end if;
  if not exists (select 1 from public.sop_document_history h join public.sop_documents x on x.id = h.document_id
                  where x.sop_number = 'FSQM-017' and h.revision = 'v13') then
    raise exception 'FSQM-017 v13 was not snapshotted.';
  end if;

  select status, revision, content->'procedure' as p into d from public.sop_documents where sop_number = 'FSQM-016';
  if d.status <> 'draft' or d.revision <> 'New' or jsonb_array_length(d.p) <> 147 then raise exception 'FSQM-016 is not 147 lines.'; end if;
  if d.p::text ~ 'checked and pull tested|checked with the pull test|every hour' or d.p->>98 not like '◦ CCP 2 CHECK AT BOXING%'
     or d.p->>134 not like '◦ CCP 2 - Vacuum sealing (step 13):%' or d.p->>136 not like '%2.4.3.12%'
     or (select count(*) from jsonb_array_elements_text(d.p) l where left(l, 1) not in ('•', '◦', '>')) <> 9 then
    raise exception 'FSQM-016 was not reworded as intended.';
  end if;
  if exists (select 1 from public.sop_documents where sop_number in ('FRM-606', 'FSQM-017')
              and content::text ~* 'Diana|Gabriela|Christina|Mercer|Pillsbury|Amazon|Sysco|Bahamas') then
    raise exception 'a document names a person, a supplier or a customer.';
  end if;
end $verify$;

commit;
